#!/usr/bin/env python3
"""v42 : brief vidéo au design de la maquette Chat v3, présentation uniquement.
- La ligne « Acteur » (photo, nom, Changer) passe DANS la carte, sous l'en-tête « Brief vidéo »
  (carte de rédaction et carte « À valider ») ; seule ailleurs (génération en cours), comme avant.
- Styles UGC / Cinématique… : texte centré verticalement dans les pastilles.
- Sections du brief : titres en petites capitales grasses, minutages discrets, « Modifier » en lien d'accent.
- Qualité : crédits à droite, sur la même ligne que Standard / Cinématique premium.
Mêmes boutons, mêmes actions. Usage : python3 apply-v42.py [--check]"""
import sys, pathlib, json
CHECK = "--check" in sys.argv
R = json.loads(r'''[["src/routes/_authenticated/create.tsx", [["  const latestMetaPreview = useMemo(() => findLatestMetaPreview(messages), [messages]);\n", "  const latestMetaPreview = useMemo(() => findLatestMetaPreview(messages), [messages]);\n  // Ligne « Acteur » (maquette Chat v3) : dans la carte du brief quand elle est affichée, seule sinon.\n  const actorGender = ((pillActorsQ.data as Array<{ id: string; gender?: string }> | undefined) ?? []).find((actor) => actor.id === selectedActorId)?.gender;\n  const actorRowVisible = Boolean(\n    (chainActive || promptPreview?.mediaType === \"video\" || (readyBrief && canPreparePrompt && String(state.mediaType ?? readyBrief?.mediaType ?? \"\") === \"video\")) &&\n    typeof state.stockActorName === \"string\" && state.stockActorName && selectedActorMedia.data?.url,\n  );\n  const briefCardShown = Boolean(readyBrief && readyBrief.sameAsLastPrompt !== true && canPreparePrompt && !promptPreview && !chainActive && !generating);\n  const actorRowNode = actorRowVisible ? (\n    <>\n      <img src={selectedActorMedia.data?.url ?? \"\"} alt={String(state.stockActorName)} />\n      <div className=\"min-w-0 flex-1\">\n        <small>Acteur</small>\n        <b>{String(state.stockActorName)}</b>{actorGender === \"female\" ? <span> · Femme · face caméra</span> : actorGender === \"male\" ? <span> · Homme · face caméra</span> : null}\n      </div>\n      <button type=\"button\" className=\"gx-btn gx-sm\" disabled={generating || chainActive || savingActorReplacement} onClick={() => {\n        setReplacingActor(true);\n        setCatalogPickerTab(\"actors\");\n        setCatalogPickerOpen(true);\n      }}>\n        Changer\n      </button>\n    </>\n  ) : null;\n  const actorInCard = actorRowNode !== null && (Boolean(promptPreview) || briefCardShown);\n"], ["          {(chainActive || promptPreview?.mediaType === \"video\" || (readyBrief && canPreparePrompt && String(state.mediaType ?? readyBrief?.mediaType ?? \"\") === \"video\")) &&\n            typeof state.stockActorName === \"string\" && state.stockActorName && selectedActorMedia.data?.url && (\n            <div className=\"gx-m-x\">\n              <div className=\"gx-kard gx-actor animate-fade-in\">\n                <img src={selectedActorMedia.data.url} alt={state.stockActorName} />\n                <div className=\"min-w-0 flex-1\">\n                  <small>Acteur</small>\n                  <b>{state.stockActorName}{(() => { const gender = ((pillActorsQ.data as Array<{ id: string; gender?: string }> | undefined) ?? []).find((actor) => actor.id === selectedActorId)?.gender; return gender === \"female\" ? \" · Femme · face caméra\" : gender === \"male\" ? \" · Homme · face caméra\" : \"\"; })()}</b>\n                </div>\n                <button type=\"button\" className=\"gx-btn gx-sm\" disabled={generating || chainActive || savingActorReplacement} onClick={() => {\n                  setReplacingActor(true);\n                  setCatalogPickerTab(\"actors\");\n                  setCatalogPickerOpen(true);\n                }}>\n                  Changer\n                </button>\n              </div>\n            </div>\n          )}\n", "          {actorRowNode && !actorInCard && (\n            <div className=\"gx-m-x\">\n              <div className=\"gx-kard gx-actor animate-fade-in\">\n                {actorRowNode}\n              </div>\n            </div>\n          )}\n"], ["                <span className={`gx-c3-status ${pill.cls}`}>{pill.label}</span>\n              </div>\n", "                <span className={`gx-c3-status ${pill.cls}`}>{pill.label}</span>\n              </div>\n              {actorRowNode && <div className=\"gx-c3-who\">{actorRowNode}</div>}\n"], ["        <span className=\"gx-c3-status gx-c3-todo\">À valider</span>\n      </div>\n", "        <span className=\"gx-c3-status gx-c3-todo\">À valider</span>\n      </div>\n      {actorSlot ? <div className=\"gx-c3-who\">{actorSlot}</div> : null}\n"], ["  costCredits,\n}: {\n  preview: {\n    mediaType: \"video\" | \"image\" | \"carousel\";", "  costCredits,\n  actorSlot,\n}: {\n  preview: {\n    mediaType: \"video\" | \"image\" | \"carousel\";"], ["  costCredits?: number | null;\n}) {", "  costCredits?: number | null;\n  /** Ligne « Acteur » affichée dans la carte, sous l'en-tête (maquette Chat v3). */\n  actorSlot?: React.ReactNode;\n}) {"], ["              preview={promptPreview}\n", "              preview={promptPreview}\n              actorSlot={actorRowNode}\n"]]]]''')
CSS_FILE = "src/styles/gx-chat-v3.css"
CSS_MARK = "/* v42 : brief vidéo"
CSS = json.loads(r'''"/* v42 : brief vidéo au design de la maquette (acteur dans la carte, styles, sections, qualité) */\n.gx-chat3 .gx-prompt>.gx-c3-who{display:flex;align-items:center;gap:12px;margin:0 16px;padding:10px 12px;border:1px solid var(--gx-c3-line);border-radius:12px;background:var(--gx-c3-raised)}\n.gx-chat3 .gx-c3-who>img{width:40px;height:40px;border-radius:50%;object-fit:cover;object-position:50% 15%;flex:none}\n.gx-chat3 .gx-c3-who small{display:block;color:var(--gx-c3-dim);font-size:12px;line-height:1.2}\n.gx-chat3 .gx-c3-who b{font-weight:600;font-size:14.5px}\n.gx-chat3 .gx-c3-who span{color:var(--gx-c3-dim);font-size:13px}\n.gx-chat3 .gx-c3-who>.gx-btn{flex:none}\n.gx-chat3 .gx-prompt>.gx-pills{display:flex;flex-wrap:wrap;gap:6px}\n.gx-chat3 .gx-pills>span{display:inline-flex;align-items:center;line-height:1;font-weight:500;white-space:nowrap}\n.gx-chat3 .gx-pills>span.gx-on{font-weight:600}\n.gx-chat3 .gx-c3-sec header>small{font-weight:700;letter-spacing:.07em}\n.gx-chat3 .gx-c3-spoken>div{padding:2px 0}\n.gx-chat3 .gx-c3-spoken small{color:var(--gx-c3-faint);font-size:12.5px;font-variant-numeric:tabular-nums;padding-top:2px}\n.gx-chat3 .gx-c3-sections .gx-c3-sec>header>button{height:26px;padding:0 4px;background:none!important;color:var(--gx-c3-accent-ink)!important;font-size:13px;font-weight:500;box-shadow:none}\n.gx-chat3 .gx-c3-sections .gx-c3-sec>header>button:hover{text-decoration:underline;text-underline-offset:3px}\n.gx-chat3 .gx-prompt>.gx-eng>button{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:10px}\n.gx-chat3 .gx-prompt>.gx-eng>button small{grid-column:2;grid-row:1;display:inline-flex;align-items:center;gap:3px;padding-left:0;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap}\n.gx-chat3 .gx-prompt>.gx-eng>button small .gx-i{width:12px;height:12px}\n@media(max-width:560px){.gx-chat3 .gx-prompt>.gx-c3-who{flex-wrap:wrap}}\n"''')
root = pathlib.Path(".")
ok = True; out = {}
for f, reps in R:
    s = (root / f).read_text()
    for old, new in reps:
        n = s.count(old)
        if n != 1:
            print(f"ÉCHEC {f}: trouvé {n} fois : {old[:90]!r}"); ok = False; continue
        s = s.replace(old, new)
    out[f] = s
cp = root / CSS_FILE; cs = cp.read_text()
if CSS_MARK in cs: print("ÉCHEC : CSS v42 déjà présent"); ok = False
if ok and not CHECK:
    for f, s in out.items(): (root / f).write_text(s)
    cp.write_text(cs.rstrip() + "\n" + CSS)
print("OK" if ok else "ÉCHEC", "(vérification seule)" if CHECK else "")
sys.exit(0 if ok else 1)
